# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the debug panel's Spend tab: AI spend from Logfire (ds.data.raw.logfire),
#          every machine and app, next to the Gateway's spending limits (ds.data.raw.gateway):
#          a tile per limit window (UTC today / this week / this month) with a meter, a bar
#          per day in local time on a labelled scale, a split by agent and model, the priciest
#          requests.
# Usage: view = load(days=30) -> SpendView (state.py, on opening the tab or Refresh).
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
import math
from dataclasses import dataclass, field
from pathlib import Path
from zoneinfo import ZoneInfo

import polars as pl
from ds.data.raw.gateway import GatewayScopeError, SpendingLimits, spending_limits
from ds.data.raw.logfire import LogfireKeyMissingError, ai_spend

from ui.session import cost_text, tokens_text

DAYS = 30
# the Gateway's limit windows: assumed UTC calendar day / ISO week / month (its docs don't say)
WINDOWS = (("daily", "Today"), ("weekly", "This week"), ("monthly", "This month"))
WARN_AT, DANGER_AT = 0.75, 0.9  # share of a limit where the meter turns warning / danger


def _local_zone() -> str:
    """The IANA time zone of this machine (from /etc/localtime),
    so days start at local midnight.
    """
    try:
        return str(Path("/etc/localtime").resolve().relative_to("/usr/share/zoneinfo"))
    except ValueError:
        return "UTC"


@dataclass
class SpendView:
    status: str = ""
    """'' (not loaded), 'ok', 'setup' (no Pydantic API key) or 'error'."""
    error: str = ""
    tiles: list[dict[str, str]] = field(default_factory=list)
    bars: list[dict[str, str]] = field(default_factory=list)
    axis: list[dict[str, str]] = field(default_factory=list)
    """The chart's tick labels, top to bottom: {"label": "$2.00", "bottom": "100%"}."""
    limit_line: dict[str, str] = field(default_factory=dict)
    """The daily limit on the chart ({"bottom", "label"}; pinned to the top when it's off the
    scale), or {} when there is no daily limit."""
    limits: str = ""
    """The one line naming every limit that applies (or why they couldn't be read)."""
    rows: list[dict[str, str]] = field(default_factory=list)
    top: list[dict[str, str]] = field(default_factory=list)
    note: str = ""
    project_url: str = ""


def window_starts(today_utc: dt.date) -> dict[str, dt.date]:
    """First UTC day of each limit window: today, this ISO week's Monday, this month's 1st."""
    return {
        "daily": today_utc,
        "weekly": today_utc - dt.timedelta(days=today_utc.weekday()),
        "monthly": today_utc.replace(day=1),
    }


def _money(dollars: float) -> str:
    """A tick or limit amount: '$5', '$0.50', '$12'."""
    return f"${dollars:,.0f}" if dollars >= 10 or dollars == int(dollars) else f"${dollars:.2f}"


def tile(label: str, frame: pl.DataFrame, cap: int | None, limits_known: bool) -> dict[str, str]:
    """One window's tile: spent, the cap it's measured
    against, the meter's fill and severity.
    """
    spent = float(frame["cost"].sum() or 0)
    requests = int(frame["requests"].sum())
    out = {
        "label": label,
        "value": cost_text(spent),
        "sub": f"{requests:,} request{'s' if requests != 1 else ''}",
        "limit": "",
        "share": "",
        "meter": "",
        "level": "",
    }
    if cap is None:
        out["limit"] = "no limit" if limits_known else ""
        return out
    share = spent / cap if cap else 1.0
    out["limit"] = f"/ {_money(cap)}"
    out["share"] = f"{100 * share:.0f}%"
    out["meter"] = f"{min(100.0, 100 * share):.1f}%"
    out["level"] = "danger" if share >= DANGER_AT else "warn" if share >= WARN_AT else "ok"
    return out


def nice_top(peak: float) -> float:
    """The chart's top: the smallest 1, 2 or 5 × 10^k
    at or above the busiest day ($1.30 -> $2).
    """
    if peak <= 0:
        return 1.0
    step = 10 ** math.floor(math.log10(peak))
    return next(m * step for m in (1, 2, 5, 10) if m * step >= peak)


def limits_text(limits: SpendingLimits) -> str:
    """'Limits: project delulu-smash $5/month · organization none'."""

    def level(caps: dict[str, int | None]) -> str:
        set_caps = [f"{_money(cap)}/{per}" for per, cap in caps.items() if cap is not None]
        return ", ".join(set_caps) or "none"

    project = {"day": limits.project.daily, "week": limits.project.weekly, "month": limits.project.monthly}
    org = {"day": limits.organization.daily, "week": limits.organization.weekly, "month": limits.organization.monthly}
    return f"Limits: project {limits.project_name} {level(project)} · organization {level(org)}"


def build(
    hourly: pl.DataFrame,
    top: pl.DataFrame,
    zone: str,
    now: dt.datetime,
    days: int = DAYS,
    limits: SpendingLimits | None = None,
    limits_problem: str = "",
) -> SpendView:
    """What the tab shows, from ai_spend's frames (hours in UTC).

    Tiles use the limit windows in UTC; the chart's bars are days in `zone`. `limits` is None
    when they couldn't be read (`limits_problem` says why).
    """
    view = SpendView(status="ok")
    today_utc = now.astimezone(dt.UTC).date()
    utc_day = pl.col("hour").dt.date()
    starts = window_starts(today_utc)
    for window, label in WINDOWS:
        cap = limits.tightest(window)[0] if limits else None
        view.tiles.append(tile(label, hourly.filter(utc_day >= starts[window]), cap, limits is not None))
    view.limits = limits_text(limits) if limits else limits_problem

    frame = hourly.with_columns(day=pl.col("hour").dt.convert_time_zone(zone).dt.date())
    today = now.astimezone(ZoneInfo(zone)).date()
    frame = frame.filter(pl.col("day") > today - dt.timedelta(days=days))
    per_day = frame.group_by("day").agg(pl.col("cost").sum(), pl.col("requests").sum())
    by_day = {row["day"]: row for row in per_day.iter_rows(named=True)}
    peak = max((float(row["cost"] or 0) for row in by_day.values()), default=0)
    scale = nice_top(peak)
    view.axis = [{"label": _money(scale * f), "bottom": f"{100 * f:.0f}%"} for f in (1, 0.5, 0)]
    # the daily limit as a dashed line (as the plan's sketch): at its height when it fits the
    # scale, else pinned to the top and labelled as off the chart
    daily_cap = limits.tightest("daily")[0] if limits else None
    if daily_cap is not None and daily_cap <= scale:
        view.limit_line = {"bottom": f"{100 * daily_cap / scale:.1f}%", "label": f"daily limit {_money(daily_cap)}"}
    elif daily_cap is not None:
        view.limit_line = {"bottom": "100%", "label": f"daily limit {_money(daily_cap)} is off the chart"}
    for back in range(days - 1, -1, -1):
        day = today - dt.timedelta(days=back)
        row = by_day.get(day, {"cost": 0, "requests": 0})
        cost = float(row["cost"] or 0)
        view.bars.append(
            {
                "height": f"{100 * cost / scale:.1f}%",
                "title": f"{day:%a %b %d}: {cost_text(cost)}, {row['requests']} requests",
                "label": f"{day:%b %d}" if back in (days - 1, 0) else "",
            }
        )

    total = float(frame["cost"].sum() or 0) or 1
    split = (
        frame.group_by("agent", "model")
        .agg(pl.col("requests", "input_tokens", "output_tokens", "cost").sum())
        .sort("cost", descending=True, nulls_last=True)
    )
    view.rows = [
        {
            "agent": row["agent"] or "(no name)",
            "model": row["model"] or "?",
            "requests": f"{row['requests']:,}",
            "tokens": f"{tokens_text(row['input_tokens'])} in · {tokens_text(row['output_tokens'])} out",
            "cost": cost_text(float(row["cost"] or 0)),
            "share": f"{100 * float(row['cost'] or 0) / total:.0f}%",
        }
        for row in split.iter_rows(named=True)
    ]
    view.top = [
        {
            "when": row["start_at"].astimezone(ZoneInfo(zone)).strftime("%b %d %H:%M"),
            "agent": row["agent"] or "(no name)",
            "tokens": f"{tokens_text(row['input_tokens'] or 0)} in · {tokens_text(row['output_tokens'] or 0)} out",
            "cost": cost_text(row["cost"]),
            "trace_id": row["trace_id"],
        }
        for row in top.iter_rows(named=True)
    ]
    unpriced = int(frame["requests"].sum() - frame["priced"].sum())
    parts = [
        "Tiles: the limit windows, in UTC (assumed; the Gateway's docs don't say).",
        f"Bars and tables: last {days} days, days in {zone}.",
    ]
    if unpriced:
        parts.append(f"{unpriced:,} request{'s' if unpriced != 1 else ''} had no cost and count as $0.")
    view.note = " ".join(parts)
    return view


def load(days: int = DAYS) -> SpendView:
    """Query Logfire (2 queries) and the Gateway's limits (3 requests); blocking: run it off
    the event loop. The tab still shows spend when the limits can't be read.
    """
    try:
        # 31 days: this month's tile reaches back to the
        # 1st, which can be 30 days and some hours ago
        spend = ai_spend(days=max(days, 31))
    except LogfireKeyMissingError:
        return SpendView(status="setup")
    except Exception as error:  # noqa: BLE001  # shown in the tab (eg a 429 when the query budget is used up)
        return SpendView(status="error", error=f"{type(error).__name__}: {error}")
    limits, problem = None, ""
    try:
        limits = spending_limits(spend.project_name)
    except GatewayScopeError as error:
        problem = f"{error} Store a key that has it with `ds settings sync`."
    except Exception as error:  # noqa: BLE001  # shown under the tiles; spend still shows
        problem = f"Limits unavailable: {type(error).__name__}: {error}"
    view = build(spend.hourly, spend.top, _local_zone(), dt.datetime.now(dt.UTC), days, limits, problem)
    view.project_url = spend.project_url
    return view
